retrieveSourcesQuery:
query($start: Int, $count: Int, $searchQuery: String, $indicatorClass: String){
			AppPARConfig_Query {
				results: indicators(start: $start, count: $count, nameContains: $searchQuery, indicatorClass: $indicatorClass) {
					values {
						id: sysID
						label: name
					}
					result
				}
			}
		}

fetchAPI.query:
GlideRecord_Query {
							pa_breakdowns(queryConditions: $queryConditions) {
								values: _results {
										data: _row_data {
											label: displayValue
											id: uniqueValue
										}
									}
								}
							}
